--
-- Table structure for table `exercises_to_workout_diary`
--

DROP TABLE IF EXISTS `exercises_to_workout_diary`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `exercises_to_workout_diary` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `workout_diary_id` bigint unsigned NOT NULL,
  `exercise_id` bigint unsigned NOT NULL,
  `unit` enum('minutes','hours','m','km','steps') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'minutes',
  `amount` int unsigned NOT NULL DEFAULT '1',
  `burned_calories` decimal(8,2) NOT NULL DEFAULT '0.00',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `exercises_to_workout_diary_exercise_id_foreign` (`exercise_id`),
